//! Built-in icon set — Lucide vector geometry as typed path data.
//!
//! Geometry is transcribed from `lucide-static@1.21.0` (the frozen
//! reference's icon authority — see
//! `reference/shadcn-gallery-v0.1/src/icons.js`, generated by
//! `scripts/build-icons.js`). Lucide is ISC-licensed with retained
//! Feather (MIT) notices; provenance and license live in
//! `assets/icons/lucide/`.
//!
//! Model: every icon is a list of path commands in Lucide's 24×24
//! viewBox, stroked with `stroke-width: 2`, `linecap: round`,
//! `linejoin: round`, `fill: none`. The backend scales the viewBox to
//! the icon's logical size and strokes the geometry — no SVG/DOM
//! machinery, and no glyph/unicode substitution.

use crate::geom::Dp;

/// One path command in the 24×24 Lucide viewBox.
#[derive(Copy, Clone, Debug, PartialEq)]
pub enum IconOp {
    MoveTo(f32, f32),
    LineTo(f32, f32),
    QuadTo(f32, f32, f32, f32),
    CubicTo(f32, f32, f32, f32, f32, f32),
    /// SVG elliptical arc (endpoint parameterization, absolute coords).
    /// `large`/`sweep` are the SVG `large-arc-flag`/`sweep-flag`.
    ArcTo {
        rx: f32,
        ry: f32,
        x_axis_rotation: f32,
        large_arc: bool,
        sweep: bool,
        x: f32,
        y: f32,
    },
    /// `<circle>` element shortcut — a closed subpath.
    Circle {
        cx: f32,
        cy: f32,
        r: f32,
    },
    /// `<rect rx>` element shortcut — a closed rounded-rect subpath.
    RoundRect {
        x: f32,
        y: f32,
        w: f32,
        h: f32,
        r: f32,
    },
    Close,
}

/// The built-in icon vocabulary. Named after the Lucide identifiers used
/// by the frozen specimens; the `name()`/`from_name` pair is the
/// deterministic id<->geometry mapping.
#[derive(Copy, Clone, Debug, Eq, PartialEq)]
pub enum Icon {
    ArrowRight,
    ArrowLeftCircle,
    Sun,
    Moon,
    Monitor,
    CircleAlert,
}

impl Icon {
    /// Lucide identifier (matches `data-icon`-adjacent naming, not the
    /// `data-icon` placement attribute).
    pub fn name(self) -> &'static str {
        match self {
            Icon::ArrowRight => "arrow-right",
            Icon::ArrowLeftCircle => "arrow-left-circle",
            Icon::Sun => "sun",
            Icon::Moon => "moon",
            Icon::Monitor => "monitor",
            Icon::CircleAlert => "circle-alert",
        }
    }

    pub fn from_name(name: &str) -> Option<Icon> {
        Some(match name {
            "arrow-right" => Icon::ArrowRight,
            "arrow-left-circle" => Icon::ArrowLeftCircle,
            "sun" => Icon::Sun,
            "moon" => Icon::Moon,
            "monitor" => Icon::Monitor,
            "circle-alert" => Icon::CircleAlert,
            _ => return None,
        })
    }

    /// The icon's path commands in the 24×24 viewBox.
    pub fn path(self) -> &'static [IconOp] {
        use IconOp::*;
        match self {
            // arrow-right: <path d="M5 12h14"/><path d="m12 5 7 7-7 7"/>
            Icon::ArrowRight => &[
                MoveTo(5.0, 12.0),
                LineTo(19.0, 12.0),
                MoveTo(12.0, 5.0),
                LineTo(19.0, 12.0),
                LineTo(12.0, 19.0),
            ],
            // arrow-left-circle: <circle cx="12" cy="12" r="10"/>
            //   <path d="m12 8-4 4 4 4"/><path d="M16 12H8"/>
            Icon::ArrowLeftCircle => &[
                Circle {
                    cx: 12.0,
                    cy: 12.0,
                    r: 10.0,
                },
                MoveTo(12.0, 8.0),
                LineTo(8.0, 12.0),
                LineTo(12.0, 16.0),
                MoveTo(16.0, 12.0),
                LineTo(8.0, 12.0),
            ],
            // sun: <circle cx="12" cy="12" r="4"/> + eight rays
            Icon::Sun => &[
                Circle {
                    cx: 12.0,
                    cy: 12.0,
                    r: 4.0,
                },
                MoveTo(12.0, 2.0),
                LineTo(12.0, 4.0),
                MoveTo(12.0, 20.0),
                LineTo(12.0, 22.0),
                MoveTo(4.93, 4.93),
                LineTo(6.34, 6.34),
                MoveTo(17.66, 17.66),
                LineTo(19.07, 19.07),
                MoveTo(2.0, 12.0),
                LineTo(4.0, 12.0),
                MoveTo(20.0, 12.0),
                LineTo(22.0, 12.0),
                MoveTo(6.34, 17.66),
                LineTo(4.93, 19.07),
                MoveTo(19.07, 4.93),
                LineTo(17.66, 6.34),
            ],
            // moon: M20.985 12.486 a9 9 0 1 1-9.473-9.472
            //   c.405-.022.617.46.402.803 a6 6 0 0 0 8.268 8.268
            //   c.344-.215.825-.004.803.401  (relative forms resolved to
            //   absolute; the last cubic returns to the start point)
            Icon::Moon => &[
                MoveTo(20.985, 12.486),
                ArcTo {
                    rx: 9.0,
                    ry: 9.0,
                    x_axis_rotation: 0.0,
                    large_arc: true,
                    sweep: true,
                    x: 11.512,
                    y: 3.014,
                },
                CubicTo(11.917, 2.992, 12.129, 3.474, 11.914, 3.817),
                ArcTo {
                    rx: 6.0,
                    ry: 6.0,
                    x_axis_rotation: 0.0,
                    large_arc: false,
                    sweep: false,
                    x: 20.182,
                    y: 12.085,
                },
                CubicTo(20.526, 11.87, 21.007, 12.081, 20.985, 12.486),
                Close,
            ],
            // monitor: <rect width="20" height="14" x="2" y="3" rx="2"/>
            //   <line x1="8" x2="16" y1="21" y2="21"/>
            //   <line x1="12" x2="12" y1="17" y2="21"/>
            Icon::Monitor => &[
                RoundRect {
                    x: 2.0,
                    y: 3.0,
                    w: 20.0,
                    h: 14.0,
                    r: 2.0,
                },
                MoveTo(8.0, 21.0),
                LineTo(16.0, 21.0),
                MoveTo(12.0, 17.0),
                LineTo(12.0, 21.0),
            ],
            // circle-alert: <circle cx="12" cy="12" r="10"/>
            //   <line x1="12" x2="12" y1="8" y2="12"/>
            //   <line x1="12" x2="12.01" y1="16" y2="16"/>
            Icon::CircleAlert => &[
                Circle {
                    cx: 12.0,
                    cy: 12.0,
                    r: 10.0,
                },
                MoveTo(12.0, 8.0),
                LineTo(12.0, 12.0),
                MoveTo(12.0, 16.0),
                LineTo(12.01, 16.0),
            ],
        }
    }

    /// Lucide stroke width in viewBox units (constant across the set).
    pub const STROKE_WIDTH: f32 = 2.0;
    /// Lucide viewBox edge — geometry scales `size / VIEWBOX`.
    pub const VIEWBOX: f32 = 24.0;
    /// Default specimen size — `size-4` (16dp).
    pub const DEFAULT_SIZE: Dp = Dp(16.0);
}
